import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const s="/assets/samco_3.DWQ-gzbV.PNG",n="/assets/samco_4%20(1).CW61T3wY.PNG",i="/assets/samco_5.Bpe5KpQg.PNG",c="/assets/samco_2%20(4).BkoaypV7.PNG",y=JSON.parse('{"title":"Samco","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/samco.md","filePath":"connect-brokers/brokers/samco.md"}'),p={name:"connect-brokers/brokers/samco.md"};function l(d,e,g,h,u,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="samco" tabindex="-1">Samco <a class="header-anchor" href="#samco" aria-label="Permalink to &quot;Samco&quot;">​</a></h1><p>Samco Securities is a leading discount broker in India offering equity, derivatives, commodity, and currency trading. Samco Trade API is a powerful RESTful API that allows traders to build customized trading applications, automate their strategies, and integrate with various algorithmic trading platforms.</p><h3 id="steps-for-integration" tabindex="-1"><strong>Steps for Integration</strong> <a class="header-anchor" href="#steps-for-integration" aria-label="Permalink to &quot;**Steps for Integration**&quot;">​</a></h3><p>Samco has moved authentication from <strong>User ID + Password</strong> to <strong>API Key + API Secret</strong>, issued from the new <a href="https://tradeapi.samco.in/app/login" target="_blank" rel="noreferrer">Samco Trade API Web Dashboard</a>. The old flow (OTP, emailed Secret API Key, and IP registration from inside Tradeboard) is deprecated and will be removed by Samco.</p><p>If you set up Samco before this change, you must redo Steps 2 to 4. Your .env currently holds your client ID and account password; it now needs the API Key and API Secret of an OAuth app.</p><h4 id="step-1-login-to-samco-website" tabindex="-1"><strong>Step 1: Login to Samco website</strong> <a class="header-anchor" href="#step-1-login-to-samco-website" aria-label="Permalink to &quot;**Step 1: Login to Samco website**&quot;">​</a></h4><p>Visit <a href="https://tradeapi.samco.in/app/login" target="_blank" rel="noreferrer">https://tradeapi.samco.in/app/login</a> and login with your client ID/Mobile number.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>The console has two sections you will use: <strong>API Keys</strong> (issue and rotate credentials) and <strong>Static IPs</strong> (whitelist the servers allowed to call the API).</p><h4 id="step-2-create-an-oauth-app-to-generate-your-api-key-and-secret" tabindex="-1"><strong>Step 2: Create an OAuth App to generate your API Key and Secret</strong> <a class="header-anchor" href="#step-2-create-an-oauth-app-to-generate-your-api-key-and-secret" aria-label="Permalink to &quot;**Step 2: Create an OAuth App to generate your API Key and Secret**&quot;">​</a></h4><p>Open <strong>Credentials &gt; API Keys</strong> and click <strong>Create New App</strong>.</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>Fill in the form.</p><p>Click <strong>Create App</strong>. An OTP is sent to your registered mobile and email. Enter it and click <strong>Verify OTP</strong>.</p><p>On success:</p><ul><li>The <strong>API Secret</strong> is displayed <strong>once, on screen</strong>. Copy it immediately.</li><li>The <strong>API Key</strong> is emailed to your registered address.</li></ul><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><blockquote><p><strong>Save your API Secret now.</strong> It is shown only once. If you lose it you must regenerate it, and regenerating revokes every active session for that app. The same applies to regenerating the API Key.</p></blockquote><blockquote><p><strong>App limit:</strong> you can have up to <strong>5 OAuth apps</strong>. Deactivating an app does not free the slot, and app deletion is not exposed in the dashboard.</p></blockquote><h4 id="step-3-whitelist-your-static-ip" tabindex="-1"><strong>Step 3: Whitelist your Static IP</strong> <a class="header-anchor" href="#step-3-whitelist-your-static-ip" aria-label="Permalink to &quot;**Step 3: Whitelist your Static IP**&quot;">​</a></h4><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><p>Open <strong>Security &gt; Static IPs</strong>. This is a SEBI requirement: order requests are accepted <strong>only</strong> from IPs you have whitelisted here.</p><ol><li>Select the <strong>App</strong> you created in Step 2.</li><li>Choose <strong>PRIMARY</strong> (required) or <strong>SECONDARY</strong> (optional backup).</li><li>Click <strong>Save</strong> and confirm with the OTP.</li></ol><h4 id="step-4-environment-configuration-x20" tabindex="-1">Step 4 : Environment Configuration <a class="header-anchor" href="#step-4-environment-configuration-x20" aria-label="Permalink to &quot;Step 4 : Environment Configuration&amp;#x20;&quot;">​</a></h4><p>After creating the app and whitelisting your IP, configure the credentials in your .env file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_samco_api_key&#39;      # emailed to you when the app was created</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_samco_api_secret&#39; # shown once in the dashboard</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/samco/callback&#39;</span></span></code></pre></div><p>Integrating with Samco <strong>APIs</strong> unlocks the ability to automate strategies, execute trades, and analyze data directly within your own infrastructure. When used with <strong>Tradeboard</strong>, you can self-host and run your entire algo trading stack, with full control and zero vendor lock-in.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/samco/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,30)])])}const b=t(p,[["render",l]]);export{y as __pageData,b as default};
